private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getLeft() == null) {
        return node; // No rotation needed for null node or left child
    }

    TreeNode<T> newParent = node.getLeft();
    TreeNode<T> newLeftChild = newParent.getRight();
    newParent.setRight(node);
    node.setLeft(newLeftChild);

    return newParent;
}
