    int numVerticesB = target.numVertices() - numVerticesA; // Number of vertices in the second set

    // Create a map to store vertices from each set
    Map<V, Integer> vertexMapA = new HashMap<>();
    Map<V, Integer> vertexMapB = new HashMap<>();

    // Populate the vertex maps
    for (V v : resultMap.keySet()) {
        if (v == null) {
            throw new IllegalArgumentException("Map must not contain null values");
        }
        if (vertexMapA.containsKey(v)) {
            throw new IllegalArgumentException("Duplicate vertex in the first set");
        }
        if (vertexMapB.containsKey(v)) {
            throw new IllegalArgumentException("Duplicate vertex in the second set");
        }
        if (vertexMapA.size() + vertexMapB.size() > target.numVertices()) {
            throw new IllegalStateException("Graph overflowing");
        }
        vertexMapA.put(v, vertexMapA.size());
        vertexMapB.put(v, vertexMapB.size() + numVerticesA);
    }

    // Allocate a graph of the appropriate size
    Graph<V,E> result = new Graph<>(target.numVertices() * 2);

    // Add edges between vertices from both sets
    for (V v : resultMap.keySet()) {
        if (v == null) {
            continue;
        }
        int indexA = vertexMapA.get(v);
        int indexB = vertexMapB.get(v);
        for (V w : resultMap.keySet()) {
            if (v == w) {
                continue;
            }
            if (w == null) {
                continue;
            }
            if (vertexMapA.containsKey(w)) {
                continue;
            }
            if (vertexMapB.containsKey(w)) {
                continue;
            }
            int indexW = vertexMapA.get(w);
            result.addEdge(v, w, new Edge<E>());
        }
    }

    // Use the result graph as a target
