public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and result map cannot be null");
    }

    // Dijkstra's algorithm to find the shortest path from one vertex to all other vertices
    Map<String, Double> dist = new HashMap<>();
    Set<String> settled = new HashSet<>();

    // Initialize distances
    for (V vertex : target.getVertices()) {
        dist.put(vertex.toString(), Double.MAX_VALUE);
    }

    // Start from the first vertex (as per the problem statement)
    dist.put(target.getVertices().iterator().next().toString(), 0.0);

    while (settled.size() < target.getVertices().size()) {
        double minDist = Double.MAX_VALUE;
        String minVertex = null;

        // Find the vertex with the minimum distance from the settled set
        for (V vertex : target.getVertices()) {
            if (!settled.contains(vertex.toString()) && dist.get(vertex.toString()) < minDist) {
                minDist = dist.get(vertex.toString());
                minVertex = vertex.toString();
            }
        }

        if (minVertex == null) {
            throw new IllegalStateException("Graph is not connected");
        }

        settled.add(minVertex);

        // Update the distances to the neighboring vertices
        List<V> adjList = target.getAdjList().get(minVertex);
        for (V neighbor : adjList) {
            double newDist = dist.get(minVertex) + (target.getEdgeWeight(minVertex, neighbor));
            if (newDist < dist.get(neighbor.toString())) {
                dist.put(neighbor.toString(), newDist);
            }
        }
    }
}
