            }
            try {
                if (classArray[i] != targetType) {
                    field = targetType.getDeclaredField(classArray[i].getName());
                } else {
                    field = null;
                }
            } catch (NoSuchFieldException | IllegalAccessException e) {
                throw new RuntimeException("Can't get field: " + classArray[i].getName(), e);
            }
            if (field.getType() != classArray[i]) {
