    if (bucket == null) {
        throw new IllegalArgumentException("The provided bucket cannot be null.");
    }
    // Check if the bucket is the head of the list
    if (this == bucket) {
        // Insert it at the end of the list
        bucket.next = this.next;
        this.next = bucket;
    } else {
        // Find the bucket that precedes the provided bucket
        Bucket current = this;
        while (current.next != bucket) {
            current = current.next;
        }
        // Insert the provided bucket after the current bucket
        current.next = bucket;
        bucket.next = bucket.next;
    }
}
