    // Check if the duration exceeds the maximum allowed fetch data duration
    if (duration > FETCH_DATA_DURATION) {
        // Throw an UnsupportedOperationException if the duration exceeds maximum allowed fetch data duration
        throw new UnsupportedOperationException("Data fetch duration exceeds maximum allowed duration");
    }
    // Create and return the list of time ranges
    List<TimeRange> timeRanges = new ArrayList<>();
    for (long time = start; time <= end; time += FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(time, Math.min(time + FETCH_DATA_DURATION, end)));
    }
    return timeRanges;
