public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null || index < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid arguments");
    }

    // Start from the first character within the specified range
    byte lastByte = 0;
    int size = 0;
    for (int i = index; i < Math.min(index + len, str.length()); i++) {
        int charValue = str.charAt(i);
        if (charValue < 0x80) {
            size++;
        } else if (charValue < 0xC0) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
        } else if (charValue < 0xE0) {
            // 2-byte UTF-8 sequence
            lastByte = (byte) (charValue >>> 6);
            size++;
        } else if (charValue < 0xF0) {
            // 3-byte UTF-8 sequence
            lastByte = (byte) (charValue >>> 4);
            size++;
        } else {
            // 4-byte UTF-8 sequence
            lastByte = (byte) (charValue >>> 2);
            size++;
        }
        int nextValue = str.charAt(i + 1);
        if ((charValue & 0xC0) == 0x80) {
            if (nextValue >= 0x80 && nextValue <= 0xBF) {
                size ++; // Mark the end of the current byte
                i++; // Move to the next character
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
            }
        }
        size++; // Count the current character
    }

    return size;
}
