import java.net.URI;
import java.util.List;
import java.util.Scanner;

public class URIUtil {

    /**
     * Decode the path component of a URI as path segments.
     * @param u the URI. If the path component is an absolute path componentthen the leading '/' is ignored and is not considered a delimiator of a path segment.
     * @param decode true if the path segments of the path componentshould be in decoded form.
     * @return the list of path segments.
     */
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) {
            throw new IllegalArgumentException("URI cannot be null");
        }

        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return List.of();
        }

        Scanner scanner = new Scanner(path);
        List<PathSegmentImpl> segments = new ArrayList<>();
        while (scanner.hasNext()) {
            String segment = scanner.next();
            if (decode) {
                segment = decodePathSegment(segment);
            }
            segments.add(new PathSegmentImpl(segment));
        }
        scanner.close();
        return segments;
    }

    private static String decodePathSegment(String segment) {
        return decodeURIComponent(segment);
    }

    private static String encodeURIComponent(String segment) {
        StringBuilder encoded = new StringBuilder();
        for (char c : segment.toCharArray()) {
            if (isReservedCharacter(c)) {
                encoded.append('%');
                encoded.append(toTwoDigitHex((int) c));
            } else {
                encoded.append(c);
            }
        }
        return encoded.toString();
    }

    private static boolean isReservedCharacter(char c) {
        return reservedChars.indexOf(c) >= 0;
    }

    private static String toTwoDigitHex(int hex) {
        return String.format("%02X", hex);
    }

    private static String reservedChars = "$-_.!~*\'()ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
}
