public InputStream next() throws IOException {
    // Assume file is the current active file in the zip archive
    File file = activeFile;

    // If no more files are available, return null
    if (file == null) {
        return null;
    }

    // Create FileInputStream to read from the file
    FileInputStream fis = new FileInputStream(file);

    // Read the next zip entry from the file
    ZipEntry zipEntry = new ZipEntry(file.getName());
    fis.read(zipEntry.getExtra()); // Ignore extra data

    // If the next zip entry is null, return null
    if (zipEntry == null) {
        return null;
    }

    // Save the next zip entry as the active file for the upcoming calls
    activeFile = new FileInputStream(zipEntry.getInputStream());

    // Return the file InputStream
    return fis;
}
