        int shift = 0;

        for (;;) {
            b = in.read();
            if (b < 0) {
                throw new IOException("Unexpected end of stream");
            }
            if ((b & ~0x7f) == 0) {
                break;
            }
            result = ((result << 7) | (b & 0x7f)) >>> shift;
