public long readRawVarint64() throws IOException {
    long value = 0;
    int flag = 0;
    int pos = 0;

    while ((flag & 0x80) != 0) {
        byte b = in.read();
        value |= ((long) (b & 0x7F)) << pos;
        flag = b >> 7;
        pos += 7;
    }

    if (pos == 64) {
        throw new IOException("Varint overflow");
    }

    value |= ((long) (in.read())) << pos;
    return value;
}
