    if (off < 0 || off > b.length) {
        throw new IllegalArgumentException("Start offset is out of bounds");
    }

    // Check if len is out of bounds
    if (len < 0) {
        throw new IllegalArgumentException("Length cannot be negative");
    }

    // Check if off + len overflows byte array length
    if (off + len > b.length) {
        throw new ArrayIndexOutOfBoundsException("Write exceeds array bounds");
    }

    // Verifies if it's the first write operation
    if (pos == 0) {
        // Verify if there are no listeners registered
        if (listeners == null || listeners.size() == 0) {
            // If no listeners, write to the data array directly
            System.arraycopy(b, off, data, 0, len);
        } else {
            // If listeners exist, invoke the writeNext on each listener
            for (EventListener l : listeners) {
                l.writeNext(b, off, len);
            }
        }
    } else {
        // If not the first write, write to the log field
        log.append(b, off, len);
        logLen += len;

        // Check if the log exceeds the maxLength
