import java.io.File;
import java.net.URL;
import java.util.stream.Collectors;

public class Main {
    /**
     * Returns the class path of the current JVM instance as an array of {@link File} objects.
     * This method iterates through the classpath of the JVM, retrieves each classpath URL, converts it to a File, and adds it to the array.
     * 
     * @return An array of {@link File} objects representing the classpath.
     */
    private static File[] classPath() {
        File[] classpath = new File[0]; // Initialize an empty file array

        // Get the system class loader
        ClassLoader classLoader = Main.class.getClassLoader();

        if (classLoader == null) {
            // If the class loader is null, return an empty array
            return classpath;
        }

        // Get the URLs from the class loader
        URL[] urls = classLoader.getResources("");

        // Collect the URLs to a List
        java.util.List<URL> urlList = Arrays.stream(urls).collect(Collectors.toList());

        // Iterate through the List and create File objects from each URL
        for (URL url : urlList) {
            classpath = java.util.Arrays merge(classpath, buildFileArrayFromClassurl(url));
        }

        return classpath;
    }

    /**
     * Builds an array of {@link File} objects from a given URL.
     * 
     * @param url The URL to convert to a File array.
     * @return An array of {@link File} objects created from the given URL.
     */
    private static File[] buildFileArrayFromClassurl(URL url) {
        try (java.io.InputStream inputStream = url.openStream()) {
            java.nio.file.Path path = java.nio.file.Paths.get(url.toURI());
            java.nio.file.File file = path.toFile();
            return new File[]{file};
        } catch (java.io.IOException e) {
            e.printStackTrace();
            return new File[]{};
        }
    }

    public static void main(String[] args) {
        // Example usage
        File[] classPath = classPath();
        for (File file : classPath) {
            System.out.println(file.getAbsolutePath());
        }
    }
}
