private static final int DEFAULT_BUFFER_SIZE = MIN_BUFFER_SIZE;

public static int writeTo(final DataOutput out,LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput is null");
    }

    if (node == null) {
        throw new NullPointerException("LinkedBuffer is null");
    }

    var byteBuffer = new ByteBuffer(DEFAULT_BUFFER_SIZE);
    Node current = node;

    while (current != null) {
        byteBuffer.write(current.getData());
        current = current.getNext();
    }

    out.write(byteBuffer.array(), 0, byteBuffer.position());
    byteBuffer.clear();

    return byteBuffer.array().length;
}
