private void writeString(String str) throws JSONException {
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            jsonBuffer += "\\\\";
        } else if (c == '"') {
            jsonBuffer += "\\\"";
        } else if (c == '\n' || c == '\r' || c == '\t') {
            jsonBuffer += "\\" + c;
        } else if (c >= 32 && c <= 126) {
            jsonBuffer += c;
        } else if (c >= 0x80 && c <= 0xFF) {
            jsonBuffer += "\\u" + Integer.toHexString(c);
        } else {
            throw new JSONException("Invalid character in string: " + c);
        }
    }
    jsonLen = jsonBuffer.length();
}

