private Object convertValue(Object value) throws Exception {
    if (value instanceof JsonObject) {
        return buildContent((JsonObject) value);
    } else if (value instanceof JsonArray) {
        JsonArray jsonArray = (JsonArray) value;
        List<Object> list = new ArrayList<>();
        for (JsonElement element : jsonArray) {
            list.add(convertValue(element));
        }
        return list;
    } else if (value instanceof JsonPrimitive) {
        JsonPrimitive jsonPrimitive = (JsonPrimitive) value;
        switch (jsonPrimitive.getType()) {
            case NUMBER:
                return jsonPrimitive.getAsNumber().doubleValue();
            case STRING:
                return jsonPrimitive.getAsString();
            case BOOLEAN:
                return jsonPrimitive.getAsBoolean();
            default:
                throw new Exception("Unexpected type: " + value.getClass().getName());
        }
    } else {
        throw new Exception("Unsupported value type: " + value.getClass().getName());
    }
}
