public final byte[] toByteArray(){
    // Check if the buffer(s) are valid and not null
    if (buffer == null || buffer.length == 0) {
        throw new IllegalArgumentException("Buffer(s) must not be null or empty");
    }

    // Copy all the bytes from the buffer to a new byte array
    int totalBytes = 0;
    for (ByteBuffer buffer : this.buffer) {
        totalBytes += buffer.limit();
    }

    byte[] byteArray = new byte[totalBytes];
    ByteBuffer byteBuffer = ByteBuffer.wrap(byteArray);
    int offset = 0;
    for (ByteBuffer buffer : this.buffer) {
        byteBuffer.put(buffer.array(), buffer.position(), buffer.limit());
        offset += buffer.limit();
    }

    byteBuffer.flip();
    return byteBuffer.array();
}
