        return null;
    }

    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char next = str.charAt(i + 1);
                result.append(next == 'n' ? '\n' : '\\' + next);
                i++; // Skip the next character
            } else {
                throw new IllegalArgumentException("Unmatched escape sequence: \\"); // Handle unbalanced escapes
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
