    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; ++i) {
        char c = str.charAt(i);
        if (c == '\\' && i < len - 1) {
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'n':
                    result.append('\n');
                    i++;
                    break;
                case 't':
                    result.append('\t');
                    i++;
                    break;
                case '\'':
                    result.append('\'');
                    i++;
                    break;
                case '\\':
                    result.append('\\');
                    i++;
                    break;
                default:
                    result.append(nextChar);
                    i++;
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}
