public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        if (i > 0 && str.charAt(i - 1) == '\\') {
            // Handle escaped characters
            i++;
            switch (str.charAt(i)) {
                case '\'':
                    result.append('\'');
                    break;
                case '\"':
                    result.append('\"');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                // Add more mappings for other escape characters as needed
                default:
                    throw new IllegalArgumentException("Invalid escape character: " + str.charAt(i));
            }
            i++;
        } else {
            // Handle non-escaped characters
            result.append(str.charAt(i));
            i++;
        }
    }

    return result.toString();
}
