            if (array[i] == null) {
                // Fill null entries with an empty string
                array[i] = "";
            }
        }
        return array;
    }

    // Test method to verify correctness
    public static void main(String[] args) {
        System.out.println(Arrays.toString(toNoNullStringArray(null))); // Should throw IllegalArgumentException
        System.out.println(Arrays.toString(toNoNullStringArray(Arrays.asList("apple", "banana", null, "cherry", null))));
    }
}
