    // Begin of iteration helper class for the graph path
    public static class Iteration<V, E> {
        private Iterator<V> nodes;
        private Iterator<E> edges;
        private E currentNodeEdge;
        private V currentNode;

        public Iteration(VertexSupplier<V> vertexSupplier,_edgeSupplier<E> edgeSupplier) {
            // Initialize graph elements
            this.nodes = new HashSet<>();
            this.edges = new TreeSet<>();
            // Populate sets with vertices and edges
        }

        public V getCurrentNode() {
            return currentNode;
        }

        public E getCurrentEdge() {
            return currentNodeEdge;
        }

        public boolean hasNext() {
            // Determine if there is an next edge and node
            return !edges.isEmpty() and !nodes.isEmpty();
        }

        public Iteration<V,E> next() {
            // Retrieve the next edge and node
            currentNodeEdge = edges.pollFirst();
            currentNode = nodes.pick(currentNodeEdge.getFrom());
            return this;
        }
    }

    // Set supplier interface
    public interface VertexSupplier<V> {
        V getNext();
    }

    // Edge supplier interface
    public interface EdgeSupplier<E> {
        E getNext();
    }
}
