private String unescapeId(String input) {
    StringBuilder escapeSequence = new StringBuilder();
    StringBuilder unescaped = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            // Check for metacharacter
            c = input.charAt(i + 1);
            switch (c) {
                case 'b':
                    unescaped.append('\b');
                    break;
                case 'n':
                    unescaped.append('\n');
                    break;
                case 't':
                    unescaped.append('\t');
                    break;
                case 'r':
                    unescaped.append('\r');
                    break;
                case '"':
                    unescaped.append('"');
                    break;
                case '/':
                    unescaped.append('/');
                    break;
                case '\\':
                    unescaped.append('\\');
                    break;
                case 'u':
                    // Four-digit Unicode escape sequence
                    String code = input.substring(i + 2, i + 6);
                    int intCode = Integer.parseInt(code, 16);
                    unescaped.append((char) intCode);
                    i += 5;
                    break;
                default:
                    // Invalid escape sequence
                    escapeSequence.append(c);
                    unescaped.append(c);
                    break;
            }
            i++; // Skip the second character in the escape sequence
        } else {
            unescaped.append(c);
        }
    }
    if (escapeSequence.length() > 0) {
        // Unescape escape sequences
        unescaped.append(escapeSequence.toString());
    }
    return unescaped.toString();
}
