    // Check if minLabel is a valid bucket index
    if (minLabel < 0 || minLabel >= bucketsByLabel.size() || bucketsByLabel.get(minLabel).isEmpty()) {
        throw new IllegalArgumentException("Invalid minLabel value");
    }

    // Initialize an empty set to store vertices that need to be moved
    Set<Integer> verticesToMove = new HashSet<>();

    // Move all elements from bucketsByLabel[minLabel] to verticesToMove
    for (int vertex : bucketsByLabel.get(minLabel)) {
        verticesToMove.add(vertex);
    }

    // Clear bucketsByLabel[minLabel]
    bucketsByLabel.get(minLabel).clear();

    // Update labels of vertices moved from minLabel to 0
    for (int vertex : verticesToMove) {
        labels.set(vertex, 0);
    }
