public static int countOccurrencesOf(String str, String sub) {
        if (str == null || sub == null) {
            throw new IllegalArgumentException("Both str and sub must not be null.");
        }

        int count = 0;
        int lastIndex = 0;

        // Find the first occurrence of sub in str
        int firstOccurrence = str.indexOf(sub);
        if (firstOccurrence == -1) {
            return count;
        }

        lastIndex = firstOccurrence;

        // Increment count for each occurrence of sub in str starting from the last found occurrence
        while ((firstIndex = str.indexOf(sub, lastIndex + 1)) != -1) {
            count++;
            lastIndex = firstIndex;
        }

        return count;
    }
}
