private boolean unlink(ListNodeImpl<E> node) {
    if (node == null || node == head) {
        return false;
    }
    ListNodeImpl<E> current = head;
    while (current.next != null && !current.next.equals(node)) {
        current = current.next;
    }
    if (current.next != null) {
        ListNodeImpl<E> next = current.next.next;
        current.next = next;
        //prepend the deleted node back so it's not in the free list
        node.prev = null;
        node.next = head;
        head = node;
        return true;
    }
    return false;
}
