	public boolean unlink(ListNodeImpl<E> node) throws NullPointerException {
		if (node == null) {
			throw new NullPointerException("Node cannot be null");
		}
		if (node == head) {
			head = node.getNext();
		} else {
			ListNodeImpl<E> previous = findPrevious(node);
			if (previous == null) {
				throw new RuntimeException("Previous node not found");
			}
			previous.setNext(node.getNext());
		}
		node.set(null);
		return true;
	}

	private ListNodeImpl<E> findPrevious(ListNodeImpl<E> node) {
		ListNodeImpl<E> current = head;
		while (current != null && current.getNext() != node) {
			current = current.getNext();
		}
		return current;
	}
