        throw new IllegalArgumentException("Terminators cannot be null");
    }

    StringBuilder token = new StringBuilder();
    char currentChar = input.charAt(index++); // 'index' should be a valid index or reset appropriately based on context

    while (!isTerminated(currentChar, terminators)) {
        token.append(currentChar);
        currentChar = input.charAt(index++);
    }

    return token.toString();
}

private boolean isTerminated(char currentChar, char[] terminators) {
    for (char terminator : terminators) {
        if (currentChar == terminator) {
            return true;
        }
    }
    return false;
}
