import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.stream.Collectors;

class Node {
    int id;
    List<Edge> neighbors;

    Node(int id) {
        this.id = id;
        neighbors = new LinkedList<>();
    }
}

class Edge {
    Node from;
    Node to;
    int weight;

    Edge(Node from, Node to, int weight) {
        this.from = from;
        this.to = to;
        this.weight = weight;
    }
}

class Graph {
    List<Node> nodes;

    Graph() {
        nodes = new LinkedList<>();
    }

    void addNode(Node node) {
        nodes.add(node);
    }

    void addEdge(Node from, Node to, int weight) {
        from.neighbors.add(new Edge(from, to, weight));
        to.neighbors.add(new Edge(to, from, weight));
    }
}

class Pair<X, Y> {
    X x;
    Y y;

    Pair(X x, Y y) {
        this.x = x;
        this.y = y;
    }
}

class Solution {
    private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
        Graph graph = new Graph();

        // Sample nodes and edges to create a graph
        Node n1 = new Node(1);
        Node n2 = new Node(2);
        Node n3 = new Node(3);
        Node n4 = new Node(4);

        graph.addNode(n1);
        graph.addNode(n2);
        graph.addNode(n3);
        graph.addNode(n4);

        graph.addEdge(n1, n2, 1);
        graph.addEdge(n1, n3, 2);
        graph.addEdge(n2, n3, 3);
        graph.addEdge(n3, n4, 4);

        // Compute the global separator list
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = computeGraphSeparatorList(graph);

        return globalSeparatorList;
    }

    private List<Pair<List<Pair<Integer, Integer>>, E>> computeGraphSeparatorList(Graph graph) {
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new LinkedList<>();

        // Iterate through each edge in the graph
        for (Node node : graph.nodes) {
            Pair<List<Pair<Integer, Integer>>, E> separatorListForNode = computeEdgeSeparatorList(node, graph);
            globalSeparatorList.add(separatorListForNode);
        }

        return globalSeparatorList;
    }

    private Pair<List<Pair<Integer, Integer>>, E> computeEdgeSeparatorList(Node node, Graph graph) {
        List<List<Pair<Integer, Integer>>> neighborhoods = generateNeighborhoods(node);

        for (int i = 0; i < neighborhoods.size(); i++) {
            for (int j = i + 1; j < neighborhoods.size(); j++) {
                List<Pair<Integer, Integer>> separatorList = smallestSeparationBetweenNeighborhoods(neighborhoods.get(i), neighborhoods.get(j));
                separatorList.add(new Pair<>(node.getId(), node.getId()));
                globalSeparatorList.add(new Pair<>(separatorList, graph.getEdge(node.getId(), node.getId())));
            }
        }

        return globalSeparatorList.stream()
          .flatMap(separatorList -> separatorList.stream())
          .collect(Collectors.toList());
    }

    private List<List<Pair<Integer, Integer>>> generateNeighborhoods(Node node) {
        List<List<Pair<Integer, Integer>>> neighborhoods = new LinkedList<>();
        for (Node neighbor : node.neighbors) {
            neighborhoods.add(Arrays.asList(new Pair<>(neighbor.id, neighbor.id)));
        }
        return neighborhoods;
    }

    private List<Pair<Integer, Integer>> smallestSeparationBetweenNeighborhoods(List<Pair<Integer, Integer>> neighborhood1, List<Pair<Integer, Integer>> neighborhood2) {
        List<Pair<Integer, Integer>> separatorList = new LinkedList<>();
        for (Pair<Integer, Integer> pair1 : neighborhood1) {
            for (Pair<Integer, Integer> pair2 : neighborhood2) {
                separatorList.add(new Pair<>( pair1.x, pair2.y));
            }
        }
        return separatorList;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = solution.computeGlobalSeparatorList();
        globalSeparatorList.forEach(separatorList -> {
            System.out.println("Edge: (" + separatorList.x.x + ", " + separatorList.x.y + ") -> (" + separatorList.y.x + ", " + separatorList.y.y + ") - Separator List: " +
                                separatorList.y.orElseThrow(() -> new RuntimeException("Edge not found")));
        });
    }
}
