import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;

/**
 * Computes the global separator list of the {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
 * @return the list of minimal separators of every edge $e$ in the inspected graph
 */
private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    HashMap<E, HashSet<Integer>> separates = new HashMap<>();
    HashSet<Integer> visited = new HashSet<>();
    for (E e : graph.edges()) {
        separates.computeIfAbsent(e, k -> new HashSet<>());
        separates.get(e).add(e);
    }

    ArrayList<Pair<List<Pair<Integer,Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edges()) {
        List<Pair<List<Pair<Integer,Integer>>, E>> localSeparatorList = computeLocalSeparatorList(e);
        globalSeparatorList.addAll(localSeparatorList);
    }

    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>, E>> computeLocalSeparatorList(E e) {
    HashSet<Integer> separatedNodes = separates.get(e);
    ArrayList<Pair<List<Pair<Integer,Integer>>, E>> localSeparatorList = new ArrayList<>();
    for (E neighbor : graph.neighbors(e)) {
        separatedNodes.remove(neighbor);
        List<Pair<List<Pair<Integer,Integer>>, E>> childrenSeparatorList = computeLocalSeparatorList(neighbor);
        for (Pair<List<Pair<Integer,Integer>>, E> childSeparator : childrenSeparatorList) {
            List<Pair<List<Pair<Integer,Integer>>, E>> combinedSeparator = new ArrayList<>();
            combinedSeparator.add(new Pair<>(childSeparator.first, new ArrayList<>()));
            combinedSeparator.addAll(childSeparator.second);
            for (Pair<Integer,Integer> pair : separatedNodes) {
                ArrayList<Pair<Integer,Integer>> newPair = new ArrayList<>(pair);
                newPair.add(childSeparator.first);
                combinedSeparator.add(new Pair<>(newPair, childSeparator.second));
            }
            localSeparatorList.add(combinedSeparator);
        }
        separatedNodes.add(neighbor);
    }
    return localSeparatorList;
}
