import java.util.*;

public class GraphSeparator {

    /**
     * Computes the global separator list of the {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
     * @return the list of minimal separators of every edge $e$ in the inspected graph
     */
    private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
        try {
            // Assume 'graph' is already defined and populated
            List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
            Set<Pair<Integer, Integer>> visited = new HashSet<>();

            for (E edge : graph.edges()) {
                // Find all minimal separators for the current edge
                List<List<Pair<Integer, Integer>>> minimalSeparators = findMinimalSeparators(edge, visited, graph);
                globalSeparatorList.addAll(minimalSeparators);
            }

            return globalSeparatorList;
        } catch (Exception e) {
            e.printStackTrace();
            return Collections.emptyList(); // Return an empty list if an error occurs
        }
    }

    // Helper function to find minimal separators for a given edge
    private List<List<Pair<Integer, Integer>>> findMinimalSeparators(E edge, Set<Pair<Integer, Integer>> visited, Graph graph) {
        List<List<Pair<Integer, Integer>>> minimalSeparators = new ArrayList<>();
        List<Integer> neighbors = graph.getNeighbors(edge);

        for (int i = 0; i < neighbors.size(); i++) {
            for (int j = i + 1; j < neighbors.size(); j++) {
                // Add minimal separators to the list
                minimalSeparators.add(graph.getMinimalSeparators(edge, neighbors.get(i), neighbors.get(j)));
            }
        }

        return minimalSeparators;
    }
}
