public class GlobalSeparatorListProcessor {

    /**
     * Computes the global separator list of the {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
     * @return the list of minimal separators of every edge $e$ in the inspected graph
     */
    private List<Pair<List<Pair<Integer, Integer>>, Edge>> computeGlobalSeparatorList(EdgeList graph) {
        List<Pair<List<Pair<Integer, Integer>>, Edge>> separatorList = new ArrayList<>();

        for (Edge edge : graph.getEdges()) {
            List<Integer> minimalSeparatorList = computeMinimalSeparatorList(graph, edge);
            separatorList.add(new Pair<>(minimalSeparatorList, edge));
        }

        return separatorList;
    }

    private List<Pair<Integer, Integer>> computeMinimalSeparatorList(EdgeList graph, Edge edge) {
        // Check for cycles in edge
        if (graph.hasCycle(edge)) {
            return null;
        }

        // Perform BFS for each vertex in the edge's neighborhood
        List<List<Integer>> separatorLists = new ArrayList<>();
        for (Integer vertex : Arrays.asList(edge.getSource(), edge.getDestination())) {
            bfs(separatorLists, vertex, new ArrayList<>(), graph);
        }

        return separatorLists;
    }

    private void bfs(List<List<Integer>> separatorLists, Integer vertex, List<Integer> visited, EdgeList graph) {
        if (visited.contains(vertex)) {
            return;
        }
        visited.add(vertex);

        List<Integer> nextVertices = new ArrayList<>();
        for (Edge neighbor : graph.getNeighbors(vertex)) {
            if (!visited.contains(neighbor.getDestination())) {
                nextVertices.add(neighbor.getDestination());
            }
        }

        if (nextVertices.isEmpty()) {
            separatorLists.add(Arrays.asList(vertex));
            return;
        }

        for (Integer nextVertex : nextVertices) {
            bfs(separatorLists, nextVertex, visited, graph);
        }

        List<Integer> separator = new ArrayList<>();
        separator.add(vertex);
        separatorLists.add(separator);
    }
}

class EdgeList {
    private List<Edge> edges;

    public EdgeList(List<Edge> edges) {
        this.edges = edges;
    }

    public List<Edge> getEdges() {
