public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and JScrollPane cannot be null");
    }

    // Try to select the row
    if (table.getSelectedRow() != row) {
        try {
            table.setCellSelectionInterval(row, row);
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("Invalid row index: " + row);
        }
    }

    // Scroll to the selected row
    ScrollPaneUtilities.scrollRectToVisible(pane.getViewport(), pane.getCellRect(row, 0, true));

    // Repaint the table to ensure the newly selected row is visible
    try {
        table.repaint();
    } catch (Exception e) {
        System.out.println("Failed to repaint the table: " + e.getMessage());
    }
}
