public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid table or row index");
    }
    if (pane == null || !(pane instanceof JTable)) {
        throw new IllegalArgumentException("Invalid JScrollPane");
    }

    table.setRowSelectionInterval(row, row); // Select the specified row
    SwingUtilities.invokeLater(() -> {
        if (table != null && pane.getViewport() != null && pane.getViewport().getView() instanceof JTable) {
            JTable viewportTable = (JTable) pane.getViewport().getView();
            viewportTable.scrollRectToVisible(new Rectangle(table.getCellRect(row, 0, false), false));
            viewportTable.repaint();
        }
    });
}
