    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid name start index");
    }

    //get the end index of the name
    int endIndex = buf.indexOf(' ', nameStart);

    // if there is no space found, cut off to the end of the string
    if (endIndex == -1) {
        endIndex = buf.length();
    }

    // append the abbreviation
    buf.insert(endIndex, buf.substring(nameStart, endIndex).toUpperCase());
}
