public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if input is null or empty
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Input cannot be null or empty");
    }

    // Check if vertices are valid within the graph
    if (!vertices.stream().allMatch(vertex -> graph.containsVertex(vertex))) {
        throw new IllegalArgumentException("Vertices must be valid within the graph");
    }

    // Check if the set of vertices induces a clique
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}
