public List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) return lowerBounds;

    // Initialize with the smallest possible value
    lowerBounds.add(Integer.MIN_VALUE);

    for (K key : keys) {
        // Find the maximum value less than the current key
        if (key == null || key.compareTo(lowerBounds.get(lowerBounds.size() - 1)) >= 0) continue;

        for (int i = lowerBounds.size() - 1; i >= 0; i--) {
            if (key.compareTo(lowerBounds.get(i)) >= 0) break;
            lowerBounds.set(i, key);
        }
    }

    return lowerBounds;
}
