    if(keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("List of keys cannot be null or empty");
    }

    List<Integer> minBound = new ArrayList<>(keys.size());

    if(keys.size() == 1) {
        minBound.add(keys.get(0).getValue());
        return minBound;
    }

    int currentMinKey = keys.get(0).getValue();
    for(int i = 1; i < keys.size(); i++) {
        currentMinKey = Math.min(currentMinKey, keys.get(i).getValue());
        minBound.add(currentMinKey);
    }

    return minBound;
}
