public static String applyRelativePath(String path, String relativePath){
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Both path and relativePath cannot be null or empty");
    }

    // Convert the relative path to absolute path based on the given path
    int relativeLength = relativePath.length();
    StringBuilder absolutePath = new StringBuilder(path);
    if (!path.endsWith("/") && !relativePath.startsWith("/")) {
        absolutePath.append("/");
    }
    absolutePath.append(relativePath);

    // Normalize the path to ensure it is standard (i.e. all traversal characters are the same)
    absolutePath = normalizePath(absolutePath.toString());

    // Replace consecutive slashes with a single one
    absolutePath = replaceConsecutiveSlashes(absolutePath.toString());

    return absolutePath.toString();
}

private static String normalizePath(String path) {
    StringBuilder normalizedPath = new StringBuilder();
    for (int i = 0; i < path.length(); i++) {
        if (!normalizedPath.isEmpty() && path.charAt(i) == '/') {
            if (normalizedPath.charAt(normalizedPath.length() - 1) != '/') {
                normalizedPath.append('/');
            }
        } else if (normalizedPath.charAt(normalizedPath.length() - 1) == '/') {
            normalizedPath.deleteCharAt(normalizedPath.length() - 1);
        }
        normalizedPath.append(path.charAt(i));
    }
    return normalizedPath.toString();
}

private static String replaceConsecutiveSlashes(String path) {
    StringBuilder result = new StringBuilder();
    boolean previousSlash = false;
    for (int i = 0; i < path.length(); i++) {
        if (path.charAt(i) == '/') {
            if (!previousSlash) {
                result.append('/');
                previousSlash = true;
            } else {
                previousSlash = false;
            }
        } else {
            result.append(path.charAt(i));
            previousSlash = false;
        }
    }
    return result.toString();
}
