/**
 * Returns the index of the last extension separator character, which is a dot.
 * This method also checks that there is no directory separator after the last dot.
 * To do this it uses  {@link #indexOfLastSeparator(String)} which will handle a file in either Unix or Windows format.
 * The output will be the same irrespective of the machine that the code is running on.
 * @param filename  the filename to find the last path separator in, null returns -1
 * @return the index of the last separator character, or -1 if thereis no such character
 */
public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int indexExtension = filename.lastIndexOf('.');
    if (indexExtension == -1) {
        return -1;
    }

    int indexOfDirectorySeparator = filename.lastIndexOf(File.separator);
    if (indexOfDirectorySeparator != -1 && indexOfDirectorySeparator >= indexExtension) {
        return -1;
    }

    return indexExtension;
}
