import java.time.Duration;
import java.time.Instant;

public boolean isExpired(long timestamp, long expiredThreshold) {
    // When visibility of current timestamp is 0, we treat it as 0 for calculating duration
    long currentTime = (timestamp == 0L) ? Duration.ZERO : Instant.ofEpochMilli(timestamp);

    // Calculate the timestamp of when data should be expired
    long expirationTimestamp = currentTime.minusMillis(expiredThreshold).toEpochMilli();

    // Determine if the data is expired. We use Instant to compare timestamps.
    return expirationTimestamp <= currentTimestamp;
}
