import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || file.isDirectory() || !file.exists()) {
        throw new IllegalArgumentException("File is null or is not a valid file");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges list is null or empty");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();

    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange == null || timeRange.getData() == null || timeRange.getData().isEmpty()) {
            throw new IllegalArgumentException("Invalid time range data");
        }
        // Simulate loading and parsing the thread snapshots based on the specified time range
        for (String line : timeRange.getData().split("\n")) {
            if (line.startsWith("@thread_snapshot")) {
                // Parse the thread snapshot data
                // Assuming the thread snapshot data is in a specific format
                ThreadSnapshot snapshot = parseThreadSnapshot(line);
                if (snapshot != null && isWithinTimeRange(snapshot.getTimestamp(), timeRange)) {
                    snapshots.add(snapshot);
                }
            }
        }
    }

    Collections.sort(snapshots, Comparator.comparing(ThreadSnapshot::getTimestamp));

    return snapshots;
}

private static ThreadSnapshot parseThreadSnapshot(String line) {
    // Parse the thread snapshot data and return a ThreadSnapshot object
    // Example parsing logic:
    String[] parts = line.split("\\s+");
    if (parts.length == 4) {
        String timestamp = parts[0];
        String threadId = parts[1];
        String method = parts[2];
        String className = parts[3];
        return new ThreadSnapshot(timestamp, threadId, method, className);
    }
    return null;
}

private static boolean isWithinTimeRange(String timestamp, ProfileAnalyzeTimeRange timeRange) {
    // Determine if the given timestamp is within the specified time range
    long time = Long.parseLong(timestamp);
    long startTime = timeRange.getStartTimestamp();
    long endTime = timeRange.getEndTimestamp();

    return startTime <= time && time <= endTime;
}
